  "src/durable-extensions.ts": "import { mkdir, mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import type { Extension } from "@earendil-works/pi-durable";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import type { DurableExtensionFactory } from "./extensions.ts";
import type { DurableUi, Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export interface DurableExtensionsOptions {
	/** The workspace (the checked-out repository). */
	cwd: string;
	/** The `agent_dir` input, relative to the workspace; a temp dir under RUNNER_TEMP when unset. */
	agentDir: string | undefined;
	/** The `trust_project` input. */
	trustProject: boolean;
	/** The GitHub UI, in comment mode on an issue or PR. */
	ui: DurableUi | undefined;
	log: Log;
	env: Record<string, string | undefined>;
}

/** The `agent_dir` input, or a fresh directory under RUNNER_TEMP. */
async function agentDirectory(
	options: DurableExtensionsOptions,
): Promise<string> {
	if (options.agentDir) {
		const dir = resolve(options.cwd, options.agentDir);
		await mkdir(dir, { recursive: true });
		return dir;
	}
	const base = options.env["RUNNER_TEMP"] || tmpdir();
	await mkdir(base, { recursive: true });
	return mkdtemp(join(base, "pi-action-agent-"));
}

/**
 * Builds the pi-durable extensions the `extensions` input declared, with the run's host options, for the thread's
 * registry. Their names must not collide with each other or with pi-action's coding tools. Their tools may: a tool
 * named like an earlier one replaces it (the last one wins, as with pi's `registerTool`), which the log says.
 */
export async function createDurableExtensions(
	factories: readonly DurableExtensionFactory[],
	options: DurableExtensionsOptions,
): Promise<Extension[]> {
	if (factories.length === 0) {
		return [];
	}
	const { cwd, trustProject, ui, log } = options;
	const agentDir = await agentDirectory(options);
	log.info(
		`pi-durable extensions: agent directory ${agentDir}, project ${trustProject ? "trusted" : "not trusted"}, ${ui ? "questions answered on GitHub" : "no UI"}`,
	);
	const names = new Set([CodingTools.name]);
	const owners = new Map(
		(CodingTools.tools ?? []).map((tool) => [tool.name, CodingTools.name]),
	);
	const extensions: Extension[] = [];
	for (const factory of factories) {
		let extension: Extension;
		try {
			// oxlint-disable-next-line eslint/no-await-in-loop -- extensions are created in order, as they were loaded
			extension = await factory.create({
				cwd,
				agentDir,
				trustProject,
				...(ui ? { ui } : {}),
				log: { info: log.info, warning: log.warning },
			});
		} catch (error) {
			throw new Error(
				`Could not create pi-durable extension ${factory.source}: ${getErrorMessage(error)}`,
				{ cause: error },
			);
		}
		if (names.has(extension.name)) {
			throw new Error(
				`pi-durable extension ${factory.source} is named "${extension.name}", which is already taken`,
			);
		}
		names.add(extension.name);
		for (const { name } of extension.tools ?? []) {
			const owner = owners.get(name);
			if (owner !== undefined && owner !== extension.name) {
				log.info(
					`pi-durable extension ${extension.name} replaces tool ${name} from ${owner}`,
				);
			}
			owners.set(name, extension.name);
		}
		log.info(
			`pi-durable extension ${extension.name} (${factory.source}): ${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"}`,
		);
		extensions.push(extension);
	}
	return extensions;
}
",
  "src/inputs.ts": "// Reading the action's inputs (see action.yml) into ActionInputs. Empty or invalid values fall back to DEFAULTS.
import type {
	CustomProviderConfig,
	ModelInputMode,
} from "./custom-provider.ts";
import { DEFAULTS } from "./defaults.ts";
import {
	DEFAULT_SNAPSHOT_LIMITS,
	type SnapshotLimits,
} from "./storage/worktree.ts";

export type InputReader = (name: string) => string;

export interface ActionInputs {
	triggerPhrase: string;
	allowedBots: string[];
	allowedUsers: string[];
	allowedAssociations: string[];
	provider: string;
	model: string;
	/** Seconds before the run is aborted. */
	timeout: number;
	githubToken: string | undefined;
	/** The provider's key, kept in memory for this run only. */
	apiKey: string | undefined;
	customProvider: CustomProviderConfig | undefined;
	promptTemplate: string | undefined;
	outputMode: "comment" | "output";
	prompt: string | undefined;
	prNumber: number | undefined;
	/** Seconds between checks for new comments while pi works. */
	pollInterval: number;
	/** pi extensions to load (npm specs or workspace paths) for the providers they register. */
	extensions: string[];
	/** Whether pi-durable extensions may load and run the repository's own configuration (`trust_project`). */
	trustProject: boolean;
	/** The agent directory for pi-durable extensions; a temp dir when unset. */
	agentDir: string | undefined;
	/** Whether a thread saves and restores the files pi left uncommitted (`worktree_snapshots`). */
	worktreeSnapshots: boolean;
	/** What a snapshot leaves out of the untracked files. */
	worktreeLimits: SnapshotLimits;
	/** `exclude_tools`: tool name globs to disable completely. */
	excludeTools: string[];
	/** `model_tools_hidden`: tool name globs the model is not offered (other tools can still call them). */
	modelToolsHidden: string[];
}

const TRUE_VALUES = new Set(["true", "1", "yes", "y", "on"]);
const FALSE_VALUES = new Set(["false", "0", "no", "n", "off"]);
const MODEL_INPUT_MODES: ReadonlySet<string> = new Set<ModelInputMode>([
	"text",
	"image",
]);
const INTEGER_PATTERN = /^\d+$/u;
const LINE_BREAK = /\r?\n/u;
/** A `#` at the start of a line or after whitespace starts a comment; `github:owner/repo#ref` keeps its `#`. */
const EXTENSION_COMMENT = /(?:^|\s)#.*$/u;
const COMPAT_INPUTS = {
	supportsDeveloperRole: "compat_supports_developer_role",
	supportsReasoningEffort: "compat_supports_reasoning_effort",
	forceAdaptiveThinking: "compat_force_adaptive_thinking",
} as const;

export function parseCsv(value: string): string[] {
	return value
		.split(",")
		.map((entry) => entry.trim())
		.filter(Boolean);
}

/**
 * pi extension specs, newline- or comma-separated. Blank lines are skipped, and so are `#` comments: whole lines, or
 * the rest of a line after a spec (`pkg@1.2.3  # why`). Comments are removed before the commas split the line.
 */
export function parseExtensionSpecs(value: string): string[] {
	return value
		.split(LINE_BREAK)
		.flatMap((line) => line.replace(EXTENSION_COMMENT, "").split(","))
		.map((spec) => spec.trim())
		.filter((spec) => spec !== "" && !spec.startsWith("#"));
}

/** true/1/yes/y/on or false/0/no/n/off, in any case; undefined for anything else. */
export function parseBoolean(value: string): boolean | undefined {
	const normalized = value.trim().toLowerCase();
	if (TRUE_VALUES.has(normalized)) {
		return true;
	}
	return FALSE_VALUES.has(normalized) ? false : undefined;
}

export function parsePositiveInteger(value: string): number | undefined {
	const normalized = value.trim();
	const parsed = INTEGER_PATTERN.test(normalized)
		? Number.parseInt(normalized, 10)
		: 0;
	return parsed > 0 ? parsed : undefined;
}

function parseModelInputModes(value: string): ModelInputMode[] {
	const modes = parseCsv(value).filter((mode): mode is ModelInputMode =>
		MODEL_INPUT_MODES.has(mode),
	);
	return modes.length > 0 ? modes : [DEFAULTS.customModelInput];
}

function readCompat(readInput: InputReader): CustomProviderConfig["compat"] {
	const compat = Object.fromEntries(
		Object.entries(COMPAT_INPUTS).flatMap(([key, name]) => {
			const value = parseBoolean(readInput(name));
			return value === undefined ? [] : [[key, value]];
		}),
	);
	return Object.keys(compat).length > 0 ? compat : undefined;
}

/** The single custom provider/model from the flat provider_* and model_* inputs; undefined without a base URL. */
export function readCustomProviderConfig(
	readInput: InputReader,
): CustomProviderConfig | undefined {
	const baseUrl = readInput("provider_base_url").trim();
	if (!baseUrl) {
		return undefined;
	}
	const apiKey = readInput("provider_api_key").trim();
	const modelName = readInput("model_name").trim();
	const compat = readCompat(readInput);
	return {
		baseUrl,
		api: readInput("provider_api") || DEFAULTS.customProviderApi,
		...(apiKey ? { apiKey } : {}),
		authHeader:
			parseBoolean(readInput("provider_auth_header")) ??
			DEFAULTS.customProviderAuthHeader,
		...(modelName ? { modelName } : {}),
		reasoning:
			parseBoolean(readInput("model_reasoning")) ??
			DEFAULTS.customModelReasoning,
		input: parseModelInputModes(readInput("model_input")),
		contextWindow:
			parsePositiveInteger(readInput("model_context_window")) ??
			DEFAULTS.customModelContextWindow,
		maxTokens:
			parsePositiveInteger(readInput("model_max_tokens")) ??
			DEFAULTS.customModelMaxTokens,
		...(compat ? { compat } : {}),
	};
}

export function readActionInputs(
	readInput: InputReader,
	env: Record<string, string | undefined> = process.env,
): ActionInputs {
	return {
		triggerPhrase: readInput("trigger_phrase") || DEFAULTS.triggerPhrase,
		allowedBots: parseCsv(readInput("allowed_bots")),
		allowedUsers: parseCsv(readInput("allowed_users")),
		allowedAssociations: parseCsv(
			readInput("allowed_associations") ||
				DEFAULTS.allowedAssociations.join(","),
		),
		provider: readInput("provider") || DEFAULTS.provider,
		model: readInput("model") || DEFAULTS.model,
		timeout: parsePositiveInteger(readInput("timeout")) ?? DEFAULTS.timeout,
		githubToken: readInput("github_token") || env["GITHUB_TOKEN"],
		apiKey: readInput("api_key") || undefined,
		customProvider: readCustomProviderConfig(readInput),
		promptTemplate: readInput("prompt_template") || undefined,
		outputMode:
			readInput("output_mode") === "output" ? "output" : DEFAULTS.outputMode,
		prompt: readInput("prompt") || undefined,
		prNumber: parsePositiveInteger(readInput("pr_number")),
		pollInterval:
			parsePositiveInteger(readInput("poll_interval")) ?? DEFAULTS.pollInterval,
		extensions: parseExtensionSpecs(readInput("extensions")),
		trustProject:
			parseBoolean(readInput("trust_project")) ?? DEFAULTS.trustProject,
		agentDir: readInput("agent_dir").trim() || undefined,
		worktreeSnapshots:
			parseBoolean(readInput("worktree_snapshots")) ??
			DEFAULTS.worktreeSnapshots,
		worktreeLimits: {
			...DEFAULT_SNAPSHOT_LIMITS,
			exclude: parseExtensionSpecs(readInput("worktree_snapshot_exclude")),
		},
		excludeTools: parseExtensionSpecs(readInput("exclude_tools")),
		modelToolsHidden: parseExtensionSpecs(readInput("model_tools_hidden")),
	};
}
",
  "action.yml": "name: 'pi-action'
description: 'Run a durable pi coding agent on GitHub issues and PRs: one conversation per thread, stored in git'
author: 'Carlos Villela'
branding:
  icon: 'cpu'
  color: 'purple'

inputs:
  github_token:
    description: 'GitHub token for API access (issues, PRs, reactions, comments)'
    required: true
  api_key:
    description: 'LLM provider API key (runtime-only; alternatively set provider-specific env vars like ANTHROPIC_API_KEY)'
    required: false
  trigger_phrase:
    description: 'Phrase to trigger pi (e.g., @pi)'
    default: '@pi'
  allowed_bots:
    description: 'Comma-separated list of allowed bot usernames'
    default: ''
  allowed_users:
    description: 'Comma-separated GitHub usernames allowed to trigger pi. If set, users must be in this list.'
    default: ''
  allowed_associations:
    description: 'Comma-separated GitHub author associations allowed to trigger pi when allowed_users is empty'
    default: 'OWNER,MEMBER'
  timeout:
    description: 'Seconds before the run is aborted (its thread is still saved)'
    default: '1800'
  poll_interval:
    description: 'Seconds between checks for new comments while pi works; new trigger comments join the running conversation'
    default: '15'
  provider:
    description: 'LLM provider (anthropic, openai, google, etc.)'
    default: 'anthropic'
  model:
    description: 'Model ID'
    default: 'claude-sonnet-5-5'
  provider_base_url:
    description: 'Base URL for a single custom provider/model (e.g., https://inference-api.nvidia.com)'
    required: false
  provider_api:
    description: 'API type for the custom provider/model'
    required: false
    default: 'openai-completions'
  provider_api_key:
    description: 'Provider apiKey config value for custom providers; can be a literal key or env var name'
    required: false
  provider_auth_header:
    description: 'Add Authorization: Bearer <key> for custom provider requests'
    required: false
    default: 'false'
  model_name:
    description: 'Display name for the custom model'
    required: false
  model_reasoning:
    description: 'Whether the custom model supports reasoning/thinking'
    required: false
    default: 'false'
  model_input:
    description: 'Comma-separated custom model input modalities (text or text,image)'
    required: false
    default: 'text'
  model_context_window:
    description: 'Context window tokens for the custom model'
    required: false
    default: '128000'
  model_max_tokens:
    description: 'Max output tokens for the custom model'
    required: false
    default: '16384'
  compat_supports_developer_role:
    description: 'Whether the OpenAI-compatible custom provider supports developer role messages'
    required: false
  compat_supports_reasoning_effort:
    description: 'Whether the OpenAI-compatible custom provider supports reasoning_effort'
    required: false
  compat_force_adaptive_thinking:
    description: 'Use adaptive thinking for an Anthropic-compatible custom model (required by Claude Opus 4.6+ and Sonnet 4.6+)'
    required: false
  extensions:
    description: 'pi extensions to load: npm package specs or paths relative to the workspace, one per line or comma-separated. pi extensions contribute the model providers they register; packages with a pi-durable extension (pi.durable in package.json) add their tools to the conversation. npm packages are installed into a temp directory without lifecycle scripts. Extensions run inside the action with the job''s permissions and environment.'
    required: false
    default: ''
  trust_project:
    description: 'Let pi-durable extensions trust the repository: load and run its own configuration (such as .pi/ files). Only for repositories whose code you would run anyway; anyone who can open a PR can change those files.'
    required: false
    default: 'false'
  agent_dir:
    description: 'Agent directory (user-level state) for pi-durable extensions, relative to the workspace; a fresh temp directory under RUNNER_TEMP when empty'
    required: false
    default: ''
  exclude_tools:
    description: 'Tools to disable completely, one per line or comma-separated; * matches any characters (for example bash). Neither the model nor other tools can call them'
    required: false
    default: ''
  model_tools_hidden:
    description: 'Tools not to offer the model, one per line or comma-separated; * matches any characters (for example read, write, edit, bash). Other tools, such as pit''s tools.*, can still call them'
    required: false
    default: ''
  worktree_snapshots:
    description: 'Save the files pi leaves uncommitted with the thread (on refs/pi/worktrees/<number>) and restore them at the start of the next run'
    required: false
    default: 'true'
  worktree_snapshot_exclude:
    description: 'Globs of untracked files never to save in a working-tree snapshot, one per line or comma-separated (for example .env*, *.pem, *.key, id_rsa*). Ignored files are never saved'
    required: false
    default: ''
  prompt_template:
    description: 'Custom prompt template with placeholder variables'
    required: false
  output_mode:
    description: 'How to deliver results: comment (post to issue/PR) or output (set action outputs only)'
    required: false
    default: 'comment'
  prompt:
    description: 'Direct prompt for the agent (requires output_mode: output when no issue/PR context is available)'
    required: false
    default: ''
  pr_number:
    description: 'Pull request number to load explicitly (useful for workflow_dispatch)'
    required: false
    default: ''

outputs:
  response:
    description: 'The agent response text when output_mode is output'
    value: ${{ steps.run-pi-action.outputs.response }}
  success:
    description: 'Whether the agent succeeded (true/false) when output_mode is output'
    value: ${{ steps.run-pi-action.outputs.success }}

runs:
  using: 'composite'
  steps:
    # pi-action runs its TypeScript directly, which needs Node.js 24. Reuse the job's Node when it is new enough;
    # otherwise set it up (from the runner's tool cache, so this is quick).
    - name: Check Node.js version
      id: node
      shell: bash
      run: |
        if node -e 'process.exit(Number(process.versions.node.split(".")[0]) >= 24 ? 0 : 1)' 2>/dev/null; then
          echo "ok=true" >> "$GITHUB_OUTPUT"
        else
          echo "ok=false" >> "$GITHUB_OUTPUT"
        fi

    - name: Set up Node.js
      if: steps.node.outputs.ok != 'true'
      uses: actions/setup-node@v6
      with:
        node-version: '24'

    - name: Install action dependencies
      shell: bash
      run: npm ci --omit=dev --ignore-scripts --no-audit --no-fund --prefix ${{ github.action_path }}

    - name: Run pi-action
      id: run-pi-action
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/index.ts
      env:
        INPUT_GITHUB_TOKEN: ${{ inputs.github_token }}
        INPUT_API_KEY: ${{ inputs.api_key }}
        INPUT_TRIGGER_PHRASE: ${{ inputs.trigger_phrase }}
        INPUT_ALLOWED_BOTS: ${{ inputs.allowed_bots }}
        INPUT_ALLOWED_USERS: ${{ inputs.allowed_users }}
        INPUT_ALLOWED_ASSOCIATIONS: ${{ inputs.allowed_associations }}
        INPUT_TIMEOUT: ${{ inputs.timeout }}
        INPUT_POLL_INTERVAL: ${{ inputs.poll_interval }}
        INPUT_PROVIDER: ${{ inputs.provider }}
        INPUT_MODEL: ${{ inputs.model }}
        INPUT_PROVIDER_BASE_URL: ${{ inputs.provider_base_url }}
        INPUT_PROVIDER_API: ${{ inputs.provider_api }}
        INPUT_PROVIDER_API_KEY: ${{ inputs.provider_api_key }}
        INPUT_PROVIDER_AUTH_HEADER: ${{ inputs.provider_auth_header }}
        INPUT_MODEL_NAME: ${{ inputs.model_name }}
        INPUT_MODEL_REASONING: ${{ inputs.model_reasoning }}
        INPUT_MODEL_INPUT: ${{ inputs.model_input }}
        INPUT_MODEL_CONTEXT_WINDOW: ${{ inputs.model_context_window }}
        INPUT_MODEL_MAX_TOKENS: ${{ inputs.model_max_tokens }}
        INPUT_COMPAT_SUPPORTS_DEVELOPER_ROLE: ${{ inputs.compat_supports_developer_role }}
        INPUT_COMPAT_SUPPORTS_REASONING_EFFORT: ${{ inputs.compat_supports_reasoning_effort }}
        INPUT_COMPAT_FORCE_ADAPTIVE_THINKING: ${{ inputs.compat_force_adaptive_thinking }}
        INPUT_EXTENSIONS: ${{ inputs.extensions }}
        INPUT_TRUST_PROJECT: ${{ inputs.trust_project }}
        INPUT_AGENT_DIR: ${{ inputs.agent_dir }}
        INPUT_EXCLUDE_TOOLS: ${{ inputs.exclude_tools }}
        INPUT_MODEL_TOOLS_HIDDEN: ${{ inputs.model_tools_hidden }}
        INPUT_WORKTREE_SNAPSHOTS: ${{ inputs.worktree_snapshots }}
        INPUT_WORKTREE_SNAPSHOT_EXCLUDE: ${{ inputs.worktree_snapshot_exclude }}
        INPUT_PROMPT_TEMPLATE: ${{ inputs.prompt_template }}
        INPUT_OUTPUT_MODE: ${{ inputs.output_mode }}
        INPUT_PROMPT: ${{ inputs.prompt }}
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}

    # Pushes the thread's refs/pi/threads/<number> (and refs/pi/worktrees/<number>) if the step above was cancelled,
    # timed out, or crashed before its own final push. Fast-forward only: it never overwrites another run's history.
    - name: Save pi thread state
      if: always()
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/push.ts
      env:
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}
"
}

value.src/extensions.ts:
import { execFile } from "node:child_process";
import {
	existsSync,
	globSync,
	readdirSync,
	readFileSync,
	statSync,
} from "node:fs";
import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import {
	basename,
	dirname,
	isAbsolute,
	join,
	relative,
	resolve,
} from "node:path";
import { fileURLToPath } from "node:url";

import type { Provider } from "@earendil-works/pi-ai/models";
import type { Extension } from "@earendil-works/pi-durable";
import { createJiti } from "jiti";

import {
	type ExtensionProviderConfig,
	parseProviderConfig,
} from "./extension-provider.ts";
import type { PromptSource } from "./prompts.ts";
import type { DurableHostOptions } from "./types.ts";
import { field, getErrorMessage, isRecord } from "./utils.ts";

type Env = Record<string, string | undefined>;

interface ExtensionLog {
	info: (msg: string) => void;
	warning: (msg: string) => void;
}

/** A provider an extension registered, applied over the built-in providers in registration order. */
export type ExtensionProvider = { id: string; source: string } & (
	| { kind: "provider"; provider: Provider }
	| { kind: "config"; config: ExtensionProviderConfig }
);

/** Runs npm with these arguments in `cwd`. */
/**
 * A pi-durable extension a package declares with `pi.durable`: its `createPiDurableExtension` factory, called with
 * the run's host options once they are known.
 */
export interface DurableExtensionFactory {
	/** The entry module, as shown in the log. */
	source: string;
	create: (options: DurableHostOptions) => Promise<Extension>;
}

/** What the `extensions` input loaded: model providers, pi-durable extensions, and prompt templates. */
export interface LoadedExtensions {
	providers: ExtensionProvider[];
	durable: DurableExtensionFactory[];
	/** Each package's `pi.prompts`, in input order. */
	prompts: PromptSource[];
}

export type NpmRunner = (
	args: string[],
	cwd: string,
	env: Env,
) => Promise<void>;

export interface LoadExtensionsOptions {
	/** The `extensions` input: npm package specs, or paths relative to `cwd`. */
	specs: readonly string[];
	/** The workspace (the checked-out repository). */
	cwd: string;
	log: ExtensionLog;
	env?: Env;
	runNpm?: NpmRunner;
}

const EXTENSION_FILE = /\.(?:[cm]?ts|[cm]?js)$/u;
const GLOB_CHARS = /[*?[{]/u;
const LOCAL_PATH = /^(?:\.{1,2}(?:[/\\]|$)|[/\\]|~[/\\])/u;
const WHITESPACE = /\s/u;
const NPM_PREFIX = "npm:";
const NPM_MAX_BUFFER = 16 * 1024 * 1024;
/** Packages pi provides to extensions; pi-action maps the ones it has to its own copies. */
const HOST_PACKAGES = ["@earendil-works/pi-ai", "@mariozechner/pi-ai"];
const PI_AI = "@earendil-works/pi-ai";
/** pi-durable, and chord (its contexts), which pi-durable extensions share with the host. */
const DURABLE_PACKAGES = [
	"@earendil-works/pi-durable",
	"@earendil-works/chord",
];
const EXTENSION_LISTS = ["tools", "sections", "hooks", "wraps", "tasks"];

type Source = { kind: "path"; path: string } | { kind: "npm"; spec: string };

export function classifySpec(spec: string, cwd: string): Source {
	if (LOCAL_PATH.test(spec)) {
		const path = spec.startsWith("~") ? join(homedir(), spec.slice(1)) : spec;
		return { kind: "path", path: resolve(cwd, path) };
	}
	const npmSpec = spec.startsWith(NPM_PREFIX)
		? spec.slice(NPM_PREFIX.length)
		: spec;
	if (spec.startsWith("git:")) {
		throw new Error(
			`Extension "${spec}": use an npm git spec instead, such as github:owner/repo#ref`,
		);
	}
	if (!npmSpec || npmSpec.startsWith("-") || WHITESPACE.test(npmSpec)) {
		throw new Error(`Extension "${spec}" is not an npm package spec or a path`);
	}
	return { kind: "npm", spec: npmSpec };
}

/** Runs npm; a failure carries npm's stderr as its message. */
const defaultRunNpm: NpmRunner = async (args, cwd, env) => {
	const {
		promise,
		resolve: done,
		reject: fail,
	} = Promise.withResolvers<undefined>();
	execFile(
		"npm",
		args,
		{ cwd, env, maxBuffer: NPM_MAX_BUFFER },
		(error, _stdout, stderr) => {
			if (error) {
				fail(new Error(stderr.trim() || error.message, { cause: error }));
			} else {
				done(undefined);
			}
		},
	);
	return promise;
};

/** npm's environment without the action's inputs (the GitHub token and api_key). */
function npmEnv(env: Env): Env {
	return Object.fromEntries(
		Object.entries(env).filter(([name]) => !name.startsWith("INPUT_")),
	);
}

/** Installs npm specs into a fresh directory under RUNNER_TEMP; returns each installed package's root. */
async function installPackages(
	specs: string[],
	env: Env,
	runNpm: NpmRunner,
): Promise<{ name: string; path: string }[]> {
	const base = env["RUNNER_TEMP"] || tmpdir();
	await mkdir(base, { recursive: true });
	const dir = await mkdtemp(join(base, "pi-action-extensions-"));
	await writeFile(
		join(dir, "package.json"),
		`${JSON.stringify({ name: "pi-action-extensions", private: true })}\n`,
	);
	try {
		await runNpm(
			[
				"install",
				"--ignore-scripts",
				"--legacy-peer-deps",
				"--omit=dev",
				"--no-audit",
				"--no-fund",
				"--prefix",
				dir,
				...specs,
			],
			dir,
			npmEnv(env),
		);
	} catch (error) {
		throw new Error(
			`npm could not install ${specs.join(", ")}: ${getErrorMessage(error)}`,
			{ cause: error },
		);
	}
	const manifest: unknown = JSON.parse(
		readFileSync(join(dir, "package.json"), "utf8"),
	);
	const installed = field(manifest, "dependencies");
	const dependencies = isRecord(installed) ? Object.keys(installed) : [];
	return dependencies.map((name) => ({
		name,
		path: join(dir, "node_modules", name),
	}));
}

/** A directory's package.json; undefined without one. */
function readManifest(dir: string): unknown {
	const path = join(dir, "package.json");
	return existsSync(path)
		? (JSON.parse(readFileSync(path, "utf8")) as unknown)
		: undefined;
}

/** The `pi` field of a directory's package.json; undefined without one. */
function readPiManifest(dir: string): unknown {
	return field(readManifest(dir), "pi");
}

function readPiExtensions(dir: string): string[] | undefined {
	const extensions = field(readPiManifest(dir), "extensions");
	return Array.isArray(extensions)
		? extensions.filter((entry) => typeof entry === "string")
		: undefined;
}

function isDirectory(path: string): boolean {
	return existsSync(path) && statSync(path).isDirectory();
}

/** pi's manifest entries (`pi.extensions`, `pi.prompts`): paths and globs, with `!` globs excluding matches. */
function manifestPaths(dir: string, entries: string[]): string[] {
	const excluded = new Set(
		entries
			.filter((entry) => entry.startsWith("!"))
			.flatMap((entry) => globSync(entry.slice(1), { cwd: dir }))
			.map((path) => resolve(dir, path)),
	);
	return entries
		.filter((entry) => !entry.startsWith("!"))
		.flatMap((entry) =>
			GLOB_CHARS.test(entry)
				? globSync(entry, { cwd: dir }).map((path) => resolve(dir, path))
				: [resolve(dir, entry)],
		)
		.filter((path) => !excluded.has(path) && existsSync(path));
}

/** The extension files of `pi.extensions` entries; a directory gives its own entries. */
function manifestEntries(dir: string, entries: string[]): string[] {
	return manifestPaths(dir, entries).flatMap((path) =>
		isDirectory(path) ? (directoryEntry(path) ?? []) : [path],
	);
}

/** A package's prompt templates (`pi.prompts`: files and directories), under its name; undefined without any. */
function findPromptSource(dir: string): PromptSource | undefined {
	const manifest = readManifest(dir);
	const prompts = field(field(manifest, "pi"), "prompts");
	if (!Array.isArray(prompts)) {
		return undefined;
	}
	const name = field(manifest, "name");
	return {
		source: typeof name === "string" && name !== "" ? name : basename(dir),
		paths: manifestPaths(
			dir,
			prompts.filter((entry) => typeof entry === "string"),
		),
	};
}

/** A directory's declared entries (`pi.extensions`) or its index.ts / index.js. */
function directoryEntry(dir: string): string[] | undefined {
	const declared = readPiExtensions(dir);
	if (declared && declared.length > 0) {
		return manifestEntries(dir, declared);
	}
	const index = ["index.ts", "index.js"]
		.map((name) => join(dir, name))
		.find((path) => existsSync(path));
	return index ? [index] : undefined;
}

/**
 * The extension files of a package or directory, found the way pi finds them: its `pi.extensions` manifest,
 * else every extension in its `extensions/` directory (one level deep), else its index.ts or index.js.
 */
export function findExtensionEntries(path: string): string[] {
	if (!isDirectory(path)) {
		return existsSync(path) ? [path] : [];
	}
	const declared = directoryEntry(path);
	if (declared) {
		return declared;
	}
	const conventional = join(path, "extensions");
	if (!isDirectory(conventional)) {
		return [];
	}
	return readdirSync(conventional, { withFileTypes: true })
		.filter(
			(entry) => !entry.name.startsWith(".") && entry.name !== "node_modules",
		)
		.flatMap((entry) => {
			const full = join(conventional, entry.name);
			if (isDirectory(full)) {
				return directoryEntry(full) ?? [];
			}
			return EXTENSION_FILE.test(entry.name) ? [full] : [];
		});
}

/** The directory of the package.json above a package's entry file. */
function packageRoot(entry: string): string {
	let dir = dirname(entry);
	while (!existsSync(join(dir, "package.json")) && dirname(dir) !== dir) {
		dir = dirname(dir);
	}
	return dir;
}

/** A package's exported subpaths (wildcards expanded, the root and package.json left out) and their files. */
function exportedSubpaths(pkg: string): [string, string][] {
	const root = packageRoot(fileURLToPath(import.meta.resolve(pkg)));
	const manifest: unknown = JSON.parse(
		readFileSync(join(root, "package.json"), "utf8"),
	);
	const exportsField = field(manifest, "exports");
	const exports = isRecord(exportsField) ? Object.entries(exportsField) : [];
	return exports.flatMap(([key, target]): [string, string][] => {
		const file = isRecord(target) ? field(target, "import") : target;
		if (typeof file !== "string" || key === "./package.json" || key === ".") {
			return [];
		}
		const name = key.slice(2);
		const star = name.indexOf("*");
		if (star === -1) {
			return [[name, resolve(root, file)]];
		}
		const [prefix = "", suffix = ""] = file.split("*");
		const dir = resolve(root, prefix);
		const files = isDirectory(dir)
			? readdirSync(dir, { recursive: true, encoding: "utf8" })
			: [];
		return files
			.filter((match) => match.endsWith(suffix))
			.map((match) => [
				`${name.slice(0, star)}${match.slice(0, match.length - suffix.length)}`,
				join(dir, match),
			]);
	});
}

/**
 * Aliases mapping pi's host packages to pi-action's copies, like pi's extension loader, so extensions share the
 * host's instances: the pi-ai root is the compat entry point (a superset of the root), pi-durable's and chord's
 * roots are their own, and each exported subpath is its own file.
 */
export function hostAliases(): Record<string, string> {
	const aliases = new Map<string, string>();
	const add = (names: readonly string[], pkg: string, rootFile: string) => {
		const subpaths = exportedSubpaths(pkg);
		for (const name of names) {
			aliases.set(name, rootFile);
			for (const [subpath, file] of subpaths) {
				aliases.set(`${name}/${subpath}`, file);
			}
		}
	};
	add(
		HOST_PACKAGES,
		PI_AI,
		fileURLToPath(import.meta.resolve(`${PI_AI}/compat`)),
	);
	for (const pkg of DURABLE_PACKAGES) {
		add([pkg], pkg, fileURLToPath(import.meta.resolve(pkg)));
	}
	return Object.fromEntries(aliases);
}

const SUPPORTED_API = new Set([
	"registerProvider",
	"unregisterProvider",
	"events",
]);

function isProvider(value: unknown): value is Provider {
	return (
		isRecord(value) &&
		typeof value["id"] === "string" &&
		isRecord(value["auth"]) &&
		["getModels", "stream", "streamSimple"].every(
			(method) => typeof value[method] === "function",
		)
	);
}

/**
 * The `pi` object an extension factory receives. It keeps provider registrations; everything else an
 * extension can do in the coding agent (tools, commands, event handlers, UI) is ignored with a warning,
 * because pi-action runs pi-durable conversations, not the coding agent.
 */
export function createExtensionApi(
	source: string,
	providers: ExtensionProvider[],
	log: ExtensionLog,
): object {
	const warned = new Set<string>();
	const api = {
		registerProvider(nameOrProvider: unknown, config?: unknown): void {
			if (isProvider(nameOrProvider)) {
				const { id } = nameOrProvider;
				providers.push({
					id,
					source,
					kind: "provider",
					provider: nameOrProvider,
				});
				return;
			}
			if (typeof nameOrProvider !== "string" || !nameOrProvider) {
				throw new Error(
					"registerProvider() takes a provider name and config, or a pi-ai Provider",
				);
			}
			const parsed = parseProviderConfig(nameOrProvider, config);
			if (parsed.ignored.length > 0) {
				log.warning(
					`${source}: provider ${nameOrProvider}: ${parsed.ignored.join(", ")} not supported by pi-action; ignored`,
				);
			}
			providers.push({
				id: nameOrProvider,
				source,
				kind: "config",
				config: parsed,
			});
		},
		unregisterProvider(name: unknown): void {
			const kept = providers.filter(
				(entry) => !(entry.id === name && entry.source === source),
			);
			providers.splice(0, providers.length, ...kept);
		},
		events: {
			on: () => () => undefined,
			emit: () => undefined,
		},
	};
	return new Proxy(api, {
		get(target, property, receiver) {
			if (typeof property !== "string" || SUPPORTED_API.has(property)) {
				const value: unknown = Reflect.get(target, property, receiver);
				return value;
			}
			if (property === "then") {
				return undefined; // not a thenable: `await pi` must not call a stub
			}
			return () => {
				if (!warned.has(property)) {
					warned.add(property);
					log.warning(
						`${source}: pi.${property}() is not supported by pi-action (only providers are); ignored`,
					);
				}
			};
		},
	});
}

/** An entry relative to the workspace when it is inside it. */
function displayPath(entry: string, cwd: string): string {
	return isAbsolute(entry) && !relative(cwd, entry).startsWith("..")
		? relative(cwd, entry)
		: entry;
}

/** A package's `pi.durable` entry module, resolved; undefined when it declares none. */
export function findDurableEntry(dir: string): string | undefined {
	if (!isDirectory(dir)) {
		return undefined;
	}
	const durable = field(readPiManifest(dir), "durable");
	if (durable === undefined) {
		return undefined;
	}
	if (typeof durable !== "string" || durable === "") {
		throw new TypeError("pi.durable in package.json must be a module path");
	}
	const entry = resolve(dir, durable);
	if (!existsSync(entry)) {
		throw new Error(`pi.durable entry ${durable} not found`);
	}
	return entry;
}

function isDurableExtension(value: unknown): value is Extension {
	return (
		isRecord(value) &&
		typeof value["name"] === "string" &&
		value["name"] !== "" &&
		EXTENSION_LISTS.every(
			(key) => value[key] === undefined || Array.isArray(value[key]),
		)
	);
}

/** A pi-durable entry's factory: its `createPiDurableExtension` export, else its default export. */
async function loadDurableEntry(
	entry: string,
	jiti: ReturnType<typeof createJiti>,
	shown: string,
): Promise<DurableExtensionFactory> {
	const module: unknown = await jiti.import(entry);
	const named = field(module, "createPiDurableExtension");
	const factory =
		typeof named === "function" ? named : field(module, "default");
	if (typeof factory !== "function") {
		throw new TypeError(
			`${shown} exports no createPiDurableExtension function (named or default)`,
		);
	}
	return {
		source: shown,
		async create(options) {
			const extension: unknown = await Reflect.apply(factory, undefined, [
				options,
			]);
			if (!isDurableExtension(extension)) {
				throw new TypeError(
					`${shown}: createPiDurableExtension() did not return a pi-durable extension (an object with a name)`,
				);
			}
			return extension;
		},
	};
}

async function loadEntry(
	entry: string,
	jiti: ReturnType<typeof createJiti>,
	providers: ExtensionProvider[],
	log: ExtensionLog,
	cwd: string,
): Promise<void> {
	const shown = displayPath(entry, cwd);
	const factory: unknown = await jiti.import(entry, { default: true });
	if (typeof factory !== "function") {
		throw new TypeError(`${shown} has no default export function`);
	}
	const before = providers.length;
	await Reflect.apply(factory, undefined, [
		createExtensionApi(shown, providers, log),
	]);
	const ids = providers.slice(before).map((p) => p.id);
	log.info(
		ids.length > 0
			? `Loaded pi extension ${shown}: provider ${ids.join(", ")}`
			: `Loaded pi extension ${shown} (it registered no provider)`,
	);
}

/**
 * Loads one installed package or path: its prompt templates (`pi.prompts`), and its pi-durable extension when it
 * declares one (`pi.durable`), else its pi extensions, for their providers.
 */
async function loadRoot(
	root: { name: string; path: string },
	jiti: ReturnType<typeof createJiti>,
	loaded: LoadedExtensions,
	log: ExtensionLog,
	cwd: string,
): Promise<void> {
	const prompts = findPromptSource(root.path);
	if (prompts !== undefined) {
		loaded.prompts.push(prompts);
	}
	const durable = findDurableEntry(root.path);
	if (durable !== undefined) {
		if ((readPiExtensions(root.path) ?? []).length > 0) {
			log.info(
				`${root.name} has a pi-durable extension (pi.durable) and pi extensions (pi.extensions); loading only the pi-durable one, as the others need pi's coding agent`,
			);
		}
		const shown = displayPath(durable, cwd);
		loaded.durable.push(await loadDurableEntry(durable, jiti, shown));
		log.info(`Loaded pi-durable extension ${shown}`);
		return;
	}
	const entries = findExtensionEntries(root.path);
	if (entries.length === 0 && prompts === undefined) {
		log.warning(
			`${root.name} has no pi extensions; it is installed for other extensions to import`,
		);
	}
	for (const entry of entries) {
		// oxlint-disable-next-line eslint/no-await-in-loop -- extensions load one after another, in order, like pi's
		await loadEntry(entry, jiti, loaded.providers, log, cwd);
	}
}

/**
 * Installs and loads the `extensions` input: the providers pi extensions register, and the pi-durable extensions
 * packages declare. npm packages are installed into a temporary directory (never the repository) without lifecycle
 * scripts; paths load in place. Extensions run in this process with its permissions and environment.
 */
export async function loadExtensions(
	options: LoadExtensionsOptions,
): Promise<LoadedExtensions> {
	const { specs, cwd, log } = options;
	const loaded: LoadedExtensions = { providers: [], durable: [], prompts: [] };
	if (specs.length === 0) {
		return loaded;
	}
	const env = options.env ?? process.env;
	const sources = specs.map((spec) => ({
		spec,
		source: classifySpec(spec, cwd),
	}));
	const npmSpecs = sources.flatMap(({ source }) =>
		source.kind === "npm" ? [source.spec] : [],
	);
	const roots = sources.flatMap(({ source }) =>
		source.kind === "path" ? [{ name: source.path, path: source.path }] : [],
	);
	if (npmSpecs.length > 0) {
		log.info(`Installing pi extensions: ${npmSpecs.join(", ")}`);
		const installed = await installPackages(
			npmSpecs,
			env,
			options.runNpm ?? defaultRunNpm,
		);
		roots.push(...installed);
	}
	const jiti = createJiti(import.meta.url, {
		moduleCache: false,
		alias: hostAliases(),
	});
	for (const root of roots) {
		if (!existsSync(root.path)) {
			throw new Error(`Extension ${root.name} not found`);
		}
		try {
			// oxlint-disable-next-line eslint/no-await-in-loop -- extensions load one after another, in order, like pi's
			await loadRoot(root, jiti, loaded, log, cwd);
		} catch (error) {
			throw new Error(
				`Could not load pi extension ${root.name}: ${getErrorMessage(error)}`,
				{ cause: error },
			);
		}
	}
	return loaded;
}

